import{_ as a,o as i,c as t,a2 as d}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/img/IM%E5%8D%B3%E6%97%B6%E9%80%9A%E8%AE%AF%E6%89%8B%E5%86%8C/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",l="/newx-doc/img/ad/zsxq_im.png",p=JSON.parse('{"title":"IM 演示","description":"","frontmatter":{},"headers":[],"relativePath":"im-preview.md","filePath":"im-preview.md","lastUpdated":null}'),r={name:"im-preview.md"};function c(h,e,u,n,m,_){return i(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="im-演示" tabindex="-1">IM 演示 <a class="header-anchor" href="#im-演示" aria-label="Permalink to &quot;IM 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><h3 id="_1-1-im-管理后台" tabindex="-1">1.1 IM 管理后台 <a class="header-anchor" href="#_1-1-im-管理后台" aria-label="Permalink to &quot;1.1 IM 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;IM 即时通讯&quot;下的「聊天」「运营管理」「内容管理」「数据统计」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>im</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><table tabindex="0"><thead><tr><th>聊天界面</th><th>聊天管理</th></tr></thead><tbody><tr><td>聊天界面</td><td>聊天管理</td></tr></tbody></table><h3 id="_1-2-im-后端" tabindex="-1">1.2 IM 后端 <a class="header-anchor" href="#_1-2-im-后端" aria-label="Permalink to &quot;1.2 IM 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构。</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-im</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-im</code> 服务</li></ul><h3 id="_1-3-im-移动端" tabindex="-1">1.3 IM 移动端 <a class="header-anchor" href="#_1-3-im-移动端" aria-label="Permalink to &quot;1.3 IM 移动端&quot;">​</a></h3><p>IM 提供 uni-app 移动端，聊天、通讯录和运营管理都可以在手机上处理，详见 <a href="./im/mobile">《移动端 IM 即时通讯》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-im</code> 目录</li></ul><p><img src="'+o+'" alt="移动端"></p><h2 id="_2-im-启动" tabindex="-1">2. IM 启动 <a class="header-anchor" href="#_2-im-启动" aria-label="Permalink to &quot;2. IM 启动&quot;">​</a></h2><p>参见 <a href="./im/build">《IM 即时通讯手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-im-交流" tabindex="-1">3. IM 交流 <a class="header-anchor" href="#_3-im-交流" aria-label="Permalink to &quot;3. IM 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+l+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>IM 即时通讯系统，提供管理后台内置的聊天能力，主要包含聊天界面和聊天管理两部分。</p><h3 id="_4-1-聊天界面" tabindex="-1">4.1 聊天界面 <a class="header-anchor" href="#_4-1-聊天界面" aria-label="Permalink to &quot;4.1 聊天界面&quot;">​</a></h3><p>对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/im/home</code> 目录，提供全屏聊天工作台：</p><ul><li>消息：私聊、群聊、频道消息三类会话，使用 IndexedDB 本地缓存会话、消息、草稿和基础资料。</li><li>通讯录：好友列表、好友申请、群列表、加群申请。</li><li>消息类型：文本、图片、语音、视频、文件、表情、名片、合并转发、频道素材。</li><li>消息动作：发送、撤回、引用回复、已读回执、@ 成员、群消息置顶。</li><li>好友关系：申请、同意、拒绝、删除、备注、置顶、免打扰、拉黑。</li><li>群组管理：创建群、邀请入群、申请进群、退群、移除成员、群主转让、管理员设置、群公告、全员禁言、成员禁言、入群审批。</li><li>音视频通话：支持私聊单人通话、群聊多人通话，可发起语音通话、视频通话和共享屏幕。</li></ul><h3 id="_4-2-聊天管理" tabindex="-1">4.2 聊天管理 <a class="header-anchor" href="#_4-2-聊天管理" aria-label="Permalink to &quot;4.2 聊天管理&quot;">​</a></h3><p>对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/im/manager</code> 目录，菜单包括：</p><ul><li>数据统计：查看总用户、总群组、日活用户、今日消息、消息趋势、用户趋势、消息类型分布、群规模分布、消息发送 TOP 10。</li><li>私聊管理：包含好友列表、好友申请、好友消息，用于查询好友关系、申请记录和私聊消息。</li><li>群聊管理：包含群聊列表、群聊申请、群聊消息，用于查询群信息、入群申请和群聊消息。</li><li>通话记录：查看音视频通话记录、参与人、通话状态、通话时长和结束原因。</li><li>敏感词管理：维护敏感词内容、标签和启用状态。</li><li>表情管理：包含系统表情、用户表情，用于维护表情包、表情图和用户上传的个人表情。</li><li>频道管理：包含频道列表、频道素材、频道消息，用于维护频道、图文素材和推送记录。</li></ul><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>IM 共 <strong>17</strong> 张业务表，表名统一以 <code>im_</code> 为前缀：</p><table tabindex="0"><thead><tr><th>模块</th><th>子前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>消息中心</td><td><code>im_private_message</code> / <code>im_group_message</code> / <code>im_conversation_read</code></td><td>3</td><td>私聊、群聊消息入库，记录消息类型、内容、状态、发送时间，以及各会话的已读位点</td></tr><tr><td>好友关系</td><td><code>im_friend*</code></td><td>2</td><td>双向好友关系、好友申请、备注、置顶、拉黑、免打扰</td></tr><tr><td>群组管理</td><td><code>im_group*</code></td><td>3</td><td>群信息、群成员、入群申请、群角色、禁言、群置顶消息</td></tr><tr><td>频道推送</td><td><code>im_channel*</code></td><td>3</td><td>频道、图文素材、频道消息推送记录</td></tr><tr><td>音视频通话</td><td><code>im_rtc*</code></td><td>2</td><td>通话主记录、参与者状态、接通与结束时间</td></tr><tr><td>其他</td><td><code>im_face*</code> / <code>im_sensitive_word</code></td><td>4</td><td>表情包、用户表情、消息敏感词配置</td></tr></tbody></table><h3 id="_5-1-消息中心" tabindex="-1">5.1 消息中心 <a class="header-anchor" href="#_5-1-消息中心" aria-label="Permalink to &quot;5.1 消息中心&quot;">​</a></h3><p>消息中心保存私聊、群聊两类聊天消息，以及各会话的已读位点：</p><ul><li><code>im_private_message</code>：私聊消息表，按发送人、接收人记录消息。</li><li><code>im_group_message</code>：群聊消息表，按发送人、群编号记录消息，支持 @ 成员、定向可见、群回执。</li><li><code>im_conversation_read</code>：会话已读表，记录每个用户在每个会话（私聊 / 群聊 / 频道）里的已读位点，是未读数与已读回执的基础。</li></ul><p>频道消息保存到 <code>im_channel_message</code>，在本文档的「频道推送」中单独说明。</p><h3 id="_5-2-好友关系" tabindex="-1">5.2 好友关系 <a class="header-anchor" href="#_5-2-好友关系" aria-label="Permalink to &quot;5.2 好友关系&quot;">​</a></h3><p>好友关系分为好友主表和申请记录：</p><ul><li><code>im_friend</code>：好友关系表，一条记录表示用户侧对某个好友的单边关系。</li><li><code>im_friend_request</code>：好友申请记录表，记录申请理由、处理结果、处理时间。</li></ul><h3 id="_5-3-群组管理" tabindex="-1">5.3 群组管理 <a class="header-anchor" href="#_5-3-群组管理" aria-label="Permalink to &quot;5.3 群组管理&quot;">​</a></h3><p>群组管理围绕群信息、成员和申请记录展开：</p><ul><li><code>im_group</code>：群信息表，记录群名称、群主、头像、公告、封禁、全员禁言、入群审批等信息。</li><li><code>im_group_member</code>：群成员表，记录成员角色、群昵称、群备注、免打扰、禁言到期时间等信息。</li><li><code>im_group_request</code>：加群申请记录表，记录主动申请或邀请入群的处理过程。</li></ul><h3 id="_5-4-频道推送" tabindex="-1">5.4 频道推送 <a class="header-anchor" href="#_5-4-频道推送" aria-label="Permalink to &quot;5.4 频道推送&quot;">​</a></h3><p>频道推送用于运营侧图文消息：</p><ul><li><code>im_channel</code>：频道表。</li><li><code>im_channel_material</code>：频道素材表，支持站内富文本和外链两类素材。</li><li><code>im_channel_message</code>：频道消息表，记录素材推送快照和接收人范围。</li></ul><h3 id="_5-5-音视频通话" tabindex="-1">5.5 音视频通话 <a class="header-anchor" href="#_5-5-音视频通话" aria-label="Permalink to &quot;5.5 音视频通话&quot;">​</a></h3><p>音视频通话由两张表记录：</p><ul><li><code>im_rtc_call</code>：通话记录表，一通通话一行，记录会话类型、媒体类型、发起人、状态和结束原因。</li><li><code>im_rtc_participant</code>：通话参与者表，一通通话中每个参与者一行，记录邀请、接听、离开等时间。</li></ul><h3 id="_5-6-其他" tabindex="-1">5.6 其他 <a class="header-anchor" href="#_5-6-其他" aria-label="Permalink to &quot;5.6 其他&quot;">​</a></h3><p>① 表情，包含系统表情包和用户个人表情：</p><ul><li><code>im_face_pack</code>：系统表情包表。</li><li><code>im_face_pack_item</code>：系统表情包项表。</li><li><code>im_face_user_item</code>：用户私有表情表。</li></ul><p>② 内容安全，用于文本消息发送前的敏感词校验：</p><ul><li><code>im_sensitive_word</code>：敏感词表。</li></ul>',49)])])}const b=a(r,[["render",c]]);export{p as __pageData,b as default};
